<?php declare(strict_types=1); use Core\Http\Router; use Modules\Notifications\Controllers\NotificationController; return function (Router $router): void { $router->group(['prefix' => 'api/notifications', 'middleware' => ['api', 'auth']], function (Router $router): void { $router->get('/', [NotificationController::class, 'index']) ->name('api.notifications.index') ->doc('List unread notifications for the current user.', [], [ 'success' => true, 'data' => ['notifications' => []], ]); $router->post('/{id}/read', [NotificationController::class, 'markRead']) ->where('id', '\d+') ->name('api.notifications.read') ->doc('Mark one notification as read.', [], [ 'success' => true, 'data' => new stdClass(), ]); $router->post('/read-all', [NotificationController::class, 'markAllRead']) ->name('api.notifications.readAll') ->doc('Mark all notifications as read.', [], [ 'success' => true, 'data' => new stdClass(), ]); }); }; 